#include <WiFi.h>

const char* WIFI_SSID = "DIR-615T-0DBC";
const char* WIFI_PASS = "23233010";

// сегменты в порядке A,B,C,D,E,F,G,DP — смотрим, к какому GPIO подключен каждый
// A = пин 11  -> GPIO 11
// B = пин 7   -> GPIO 7
// C = пин 4   -> GPIO 4
// D = пин 2   -> GPIO 2
// E = пин 1   -> GPIO 1
// F = пин 10  -> GPIO 10
// G = пин 5   -> GPIO 5
// DP = пин 3  -> GPIO 3
const int SEG_PINS[8] = {11, 7, 4, 2, 1, 10, 5, 3};

// разряды 1..4
// разряд 1 = пин 12 -> GPIO 12
// разряд 2 = пин 9  -> GPIO 9
// разряд 3 = пин 8  -> GPIO 8
// разряд 4 = пин 6  -> GPIO 6
const int DIG_PINS[4] = {12, 9, 8, 6};

const bool COMMON_ANODE = true;

byte digitPatterns[10] = {
  0b00111111, 0b00000110, 0b01011011, 0b01001111, 0b01100110,
  0b01101101, 0b01111101, 0b00000111, 0b01111111, 0b01101111
};

byte displayBuf[4] = {0, 0, 0, 0};

unsigned long lastBlink = 0;
bool colonOn = true;

void writeSegments(byte pattern) {
  for (int i = 0; i < 8; i++) {
    bool on = (pattern >> i) & 1;
    if (COMMON_ANODE) on = !on;
    digitalWrite(SEG_PINS[i], on ? HIGH : LOW);
  }
}

void setup() {
  for (int i = 0; i < 8; i++) pinMode(SEG_PINS[i], OUTPUT);
  for (int i = 0; i < 4; i++) pinMode(DIG_PINS[i], OUTPUT);

  WiFi.mode(WIFI_STA);
  WiFi.setTxPower(WIFI_POWER_8_5dBm);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) delay(300);

  configTime(3 * 3600, 0, "pool.ntp.org");
}

void updateTime() {
  struct tm t;
  if (!getLocalTime(&t, 0)) {
    for (int i = 0; i < 4; i++) displayBuf[i] = 0x40;
    return;
  }

  int h = t.tm_hour;
  int m = t.tm_min;
  displayBuf[0] = digitPatterns[h / 10];
  displayBuf[1] = digitPatterns[h % 10];
  displayBuf[2] = digitPatterns[m / 10];
  displayBuf[3] = digitPatterns[m % 10];
}

void loop() {
  updateTime();

  if (millis() - lastBlink >= 500) {
    lastBlink = millis();
    colonOn = !colonOn;
  }
  if (colonOn) displayBuf[1] |= 0x80;

  for (int d = 0; d < 4; d++) {
    for (int i = 0; i < 4; i++) digitalWrite(DIG_PINS[i], LOW);
    writeSegments(displayBuf[d]);
    digitalWrite(DIG_PINS[d], HIGH);
    delay(2);
  }
}
